declare
  content jsonb := '{"packVersion":"tec-escola-bncc-guided-study-v13","contentVersion":6,"officialSourceUrl":"https://basenacionalcomum.mec.gov.br/images/historico/BNCC_EnsinoMedio_embaixa_site_110518.pdf","recommendedGrade":1,"recommendedGradeSource":"TECESCOLA_PEDAGOGICAL_SEQUENCE","conversionAudit":{"sourcePack":"TECESCOLA_BNCC_DEEP_LEARNING_V8","reviewType":"AUTOMATED_TECHNICAL_CONTENT_RECONCILIATION","humanCertification":"NOT_CLAIMED","sourceRecordsMutated":false,"reviewCriteria":["Recheck the official BNCC code, area, descriptor, and printed page.","Recheck the concept and arithmetic, one supported answer, and explanation consistency.","Recheck alignment of the item purpose and cognitive task with the skill.","Keep converted records versioned separately; never clear legacy demo markers in place."],"questions":[{"skillCode":"EM13MAT101","contentQuestionId":"mat-probe-01","sourceQuestionId":"v8-mat-probe-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13MAT101","contentQuestionId":"mat-practice-01","sourceQuestionId":"v8-mat-practice-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13MAT101","contentQuestionId":"mat-practice-02","sourceQuestionId":null,"action":"NEW_PRACTICE_VARIATION"},{"skillCode":"EM13MAT101","contentQuestionId":"mat-transfer-01","sourceQuestionId":"v8-mat-transfer-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13MAT101","contentQuestionId":"mat-lock-01","sourceQuestionId":"v8-mat-lock-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13MAT101","contentQuestionId":"mat-review-01","sourceQuestionId":"v8-mat-review-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13LGG303","contentQuestionId":"lgg-probe-01","sourceQuestionId":"v8-lgg-probe-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13LGG303","contentQuestionId":"lgg-practice-01","sourceQuestionId":"v8-lgg-practice-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13LGG303","contentQuestionId":"lgg-practice-02","sourceQuestionId":null,"action":"NEW_PRACTICE_VARIATION"},{"skillCode":"EM13LGG303","contentQuestionId":"lgg-transfer-01","sourceQuestionId":"v8-lgg-transfer-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13LGG303","contentQuestionId":"lgg-lock-01","sourceQuestionId":"v8-lgg-lock-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13LGG303","contentQuestionId":"lgg-review-01","sourceQuestionId":"v8-lgg-review-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CNT101","contentQuestionId":"cnt-probe-01","sourceQuestionId":"v8-cnt-probe-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CNT101","contentQuestionId":"cnt-practice-01","sourceQuestionId":"v8-cnt-practice-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CNT101","contentQuestionId":"cnt-practice-02","sourceQuestionId":null,"action":"NEW_PRACTICE_VARIATION"},{"skillCode":"EM13CNT101","contentQuestionId":"cnt-transfer-01","sourceQuestionId":"v8-cnt-transfer-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CNT101","contentQuestionId":"cnt-lock-01","sourceQuestionId":"v8-cnt-lock-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CNT101","contentQuestionId":"cnt-review-01","sourceQuestionId":"v8-cnt-review-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CHS103","contentQuestionId":"chs-probe-01","sourceQuestionId":"v8-chs-probe-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CHS103","contentQuestionId":"chs-practice-01","sourceQuestionId":"v8-chs-practice-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CHS103","contentQuestionId":"chs-practice-02","sourceQuestionId":null,"action":"NEW_PRACTICE_VARIATION"},{"skillCode":"EM13CHS103","contentQuestionId":"chs-transfer-01","sourceQuestionId":"v8-chs-transfer-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CHS103","contentQuestionId":"chs-lock-01","sourceQuestionId":"v8-chs-lock-01","action":"REAUTHORED_AND_REVALIDATED"},{"skillCode":"EM13CHS103","contentQuestionId":"chs-review-01","sourceQuestionId":"v8-chs-review-01","action":"REAUTHORED_AND_REVALIDATED"}]},"skills":[{"code":"EM13MAT101","area":"MATEMATICA","domain":"VARIACAO_E_GRAFICOS","officialPage":525,"title":"Interpretar variações por gráficos e taxas","officialDescription":"Interpretar situações econômicas, sociais e das Ciências da Natureza que envolvem a variação de duas grandezas, pela análise dos gráficos das funções representadas e das taxas de variação, com ou sem apoio de tecnologias digitais.","lesson":{"title":"Ler variações, gráficos e taxas","summary":"Uma função relaciona grandezas; seus gráficos e taxas ajudam a comparar mudanças sem perder de vista unidades, escalas e contexto.","content":"## Grandezas que variam\n\nUma situação pode relacionar duas grandezas, como tempo e distância, quantidade e custo ou volume e preço. Uma função representa como cada valor de entrada se associa a um valor de saída. No gráfico, verifique o que cada eixo representa, as unidades, a escala e o intervalo observado antes de interpretar a forma da curva.\n\nA taxa média de variação entre dois pontos é a razão entre a mudança da grandeza dependente e a mudança da independente. Em uma reta, essa taxa é constante; em uma curva, pode variar conforme o intervalo. Uma taxa negativa indica redução no sentido definido pelos eixos, não necessariamente um valor negativo da própria grandeza.\n\nGráficos permitem comparar tendências, mas não provam sozinhos causas. Uma previsão precisa declarar o intervalo e as hipóteses usadas. Tecnologias digitais ajudam a explorar dados, desde que a escala e a fonte permaneçam explícitas.","workedExample":"Uma conta de água aumenta de R$ 30 para R$ 42 quando o consumo passa de 5 m³ para 8 m³. A variação média é (42 - 30) / (8 - 5) = R$ 4 por m³ nesse intervalo. Isso não garante que a tarifa marginal seja igual em qualquer faixa de consumo.","tips":["Leia título, eixos, unidades e escala antes da curva.","Calcule a taxa usando o mesmo intervalo nos dois eixos.","Não transforme associação observada em causa sem evidência adicional."],"estimatedMinutes":10},"questions":[{"id":"mat-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"TAXA_MEDIA","statement":"Uma grandeza passa de 10 para 22 unidades enquanto o tempo passa de 2 para 5 horas. Qual é a taxa média de variação?","options":["4 unidades por hora","6 unidades por hora","12 unidades por hora","32 unidades por hora"],"answer":"4 unidades por hora","explanation":"A variação da grandeza é 22 - 10 = 12 e a do tempo é 5 - 2 = 3; a razão 12 / 3 é 4 unidades por hora."},{"id":"mat-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"CUSTO_E_QUANTIDADE","statement":"Um serviço custa R$ 18 para 2 unidades e R$ 30 para 5 unidades. Qual é o aumento médio do custo por unidade nesse intervalo?","options":["R$ 3 por unidade","R$ 4 por unidade","R$ 6 por unidade","R$ 12 por unidade"],"answer":"R$ 4 por unidade","explanation":"O custo aumenta R$ 12 e a quantidade aumenta 3 unidades. A razão entre as variações é 12 / 3 = R$ 4 por unidade."},{"id":"mat-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"ESCALA_DE_GRAFICO","statement":"Em um gráfico, o eixo vertical aumenta de 20 em 20, embora os intervalos visuais sejam iguais. O que deve ser feito ao comparar dois pontos?","options":["Usar os valores indicados pela escala, não apenas a distância visual","Tratar cada intervalo como uma unidade","Ignorar os rótulos porque a linha é contínua","Comparar somente a cor dos pontos"],"answer":"Usar os valores indicados pela escala, não apenas a distância visual","explanation":"A escala define o valor de cada intervalo; distância visual igual não significa variação numérica igual se os eixos forem graduados de outra forma."},{"id":"mat-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"CONSUMO_DE_ENERGIA","statement":"Uma escola compara o consumo mensal antes e depois de instalar lâmpadas mais eficientes. Qual procedimento sustenta melhor a comparação?","options":["Comparar períodos de duração semelhante e considerar ocupação e condições de uso","Escolher apenas o mês de menor consumo após a troca","Atribuir toda diferença às lâmpadas sem observar outros fatores","Comparar a conta em reais sem considerar mudanças de tarifa"],"answer":"Comparar períodos de duração semelhante e considerar ocupação e condições de uso","explanation":"Períodos e condições comparáveis ajudam a interpretar a variação; tarifa, ocupação e duração podem alterar o resultado sem relação com as lâmpadas."},{"id":"mat-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"INTERVALO_E_TAXA","statement":"Uma curva crescente fica quase horizontal entre dois pontos e depois se inclina mais. Qual interpretação é adequada?","options":["A taxa média de crescimento é menor no trecho quase horizontal e maior no trecho mais inclinado, respeitando as escalas","A grandeza deixa de existir no trecho horizontal","A taxa é constante em toda curva porque ela sempre cresce","O trecho mais inclinado prova que a causa mudou"],"answer":"A taxa média de crescimento é menor no trecho quase horizontal e maior no trecho mais inclinado, respeitando as escalas","explanation":"A inclinação representa taxa de variação no intervalo, desde que eixos e escalas sejam considerados; ela não identifica por si só uma causa."},{"id":"mat-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"PREDICT","contextFamily":"LIMITES_DE_MODELO","statement":"Uma função ajustada aos dados dos primeiros meses é usada para prever o próximo ano. Qual cuidado é essencial?","options":["Verificar se o intervalo e as condições da previsão são compatíveis com os dados e explicitar as hipóteses","Assumir que a função continuará válida para qualquer período","Apagar os dados que não seguem exatamente a curva","Usar a previsão como prova de que a tendência causará o resultado"],"answer":"Verificar se o intervalo e as condições da previsão são compatíveis com os dados e explicitar as hipóteses","explanation":"Modelos são úteis dentro de condições e intervalos justificados; extrapolar sem avaliar mudanças pode produzir previsões inadequadas."}]},{"code":"EM13LGG303","area":"LINGUAGENS","domain":"DEBATE_E_ARGUMENTACAO","officialPage":485,"title":"Debater com argumentos e responsabilidade","officialDescription":"Debater questões polêmicas de relevância social, analisando diferentes argumentos e opiniões manifestados, para negociar e sustentar posições, formular propostas, e intervir e tomar decisões democraticamente sustentadas, que levem em conta o bem comum e os Direitos Humanos, a consciência socioambiental e o consumo responsável em âmbito local, regional e global.","lesson":{"title":"Sustentar posições em debates públicos","summary":"Um debate responsável examina argumentos e evidências, reconhece direitos e divergências e transforma posições em propostas discutíveis.","content":"## Da opinião à deliberação\n\nEm um debate de relevância social, distinguir tese, razão, evidência e consequência torna a discussão mais clara. Uma opinião pode iniciar uma posição, mas sua sustentação melhora quando apresenta fontes pertinentes, explica como elas apoiam a conclusão e reconhece limites ou contrapontos.\n\nAnalisar diferentes argumentos não significa tratar todas as afirmações como igualmente comprovadas. Verifique autoria, contexto, dados, interesses e pessoas afetadas. Em seguida, procure pontos de desacordo e possibilidades de negociação sem apagar direitos fundamentais.\n\nUma proposta democrática explicita o problema, indica uma ação viável e considera quem será beneficiado ou onerado. Bem comum, Direitos Humanos, consciência socioambiental e consumo responsável são critérios de análise, não slogans que substituem evidências. Uma decisão pode ser revista quando novos dados ou efeitos aparecem.","workedExample":"Em uma discussão sobre reduzir descartáveis na escola, estudantes podem comparar dados de resíduos, ouvir trabalhadores da cantina e propor alternativas graduais. A proposta fica mais forte quando avalia custo, acesso, impacto ambiental e formas de acompanhar os resultados.","tips":["Separe afirmação, razão e evidência.","Examine quem é afetado e quais direitos estão envolvidos.","Formule uma proposta viável e aberta a avaliação."],"estimatedMinutes":10},"questions":[{"id":"lgg-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"ARGUMENTO_PUBLICO","statement":"Em um debate sobre reduzir descartáveis, qual fala apresenta uma proposta acompanhada de justificativa verificável?","options":["A escola deve testar copos reutilizáveis por um mês e comparar a quantidade de resíduos","Essa ideia é boa porque todo mundo sabe que sim","Quem discorda não se importa com o planeta","Devemos mudar tudo imediatamente sem avaliar custos"],"answer":"A escola deve testar copos reutilizáveis por um mês e comparar a quantidade de resíduos","explanation":"A fala propõe uma ação e indica uma evidência que pode ser observada para avaliar seu efeito."},{"id":"lgg-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"EVIDENCIA_E_Tese","statement":"Uma campanha afirma que o desperdício caiu depois de uma nova regra e apresenta apenas uma foto do pátio. Qual informação ajudaria mais a avaliar a afirmação?","options":["Registros comparáveis de resíduos antes e depois da regra","A cor do cartaz da campanha","A opinião de quem criou o cartaz","O número de curtidas da publicação"],"answer":"Registros comparáveis de resíduos antes e depois da regra","explanation":"Registros medidos com critérios semelhantes podem indicar se houve mudança; a foto e as curtidas não quantificam a variação."},{"id":"lgg-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"DIREITOS_E_PROPOSTAS","statement":"Uma proposta popular restringe a participação de um grupo sem apresentar motivo relacionado ao problema. Qual análise é mais responsável?","options":["Examinar a justificativa, os efeitos sobre direitos e alternativas menos restritivas","Aprovar sem análise porque a maioria apoiou","Rejeitar qualquer decisão tomada em grupo","Atacar quem propôs a medida em vez de avaliar seus efeitos"],"answer":"Examinar a justificativa, os efeitos sobre direitos e alternativas menos restritivas","explanation":"Decisões democráticas também devem considerar direitos, proporcionalidade e alternativas adequadas ao problema."},{"id":"lgg-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"CONSUMO_RESPONSAVEL","statement":"Um município quer reduzir embalagens descartáveis no comércio local. Qual proposta articula melhor debate e ação responsável?","options":["Construir a medida com comerciantes e consumidores, definir metas e acompanhar resíduos e acessibilidade","Proibir toda embalagem amanhã sem ouvir os afetados","Fazer uma campanha sem indicar ações ou avaliação","Escolher uma solução apenas pela popularidade nas redes"],"answer":"Construir a medida com comerciantes e consumidores, definir metas e acompanhar resíduos e acessibilidade","explanation":"A proposta inclui participação, critérios observáveis e consideração de impactos sociais e ambientais."},{"id":"lgg-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"NEGOCIACAO","statement":"Dois grupos concordam que o pátio precisa de sombra, mas divergem sobre retirar vagas de estacionamento. Qual encaminhamento favorece uma deliberação consistente?","options":["Comparar alternativas, impactos e evidências e negociar critérios que contemplem os grupos afetados","Encerrar a conversa porque existe desacordo","Escolher a alternativa do grupo mais numeroso sem justificativa","Adiar indefinidamente qualquer coleta de informações"],"answer":"Comparar alternativas, impactos e evidências e negociar critérios que contemplem os grupos afetados","explanation":"A deliberação pode avançar ao explicitar critérios, examinar consequências e negociar sem ocultar o conflito."},{"id":"lgg-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"CREATE","contextFamily":"PROPOSTA_DEMOCRATICA","statement":"Qual estrutura torna uma proposta de debate público mais avaliável?","options":["Problema delimitado, evidências, ação, impactos previstos e forma de acompanhar resultados","Frase de efeito, sem indicar a mudança desejada","Opinião repetida como se fosse dado","Conclusão que ignora contrapontos e pessoas afetadas"],"answer":"Problema delimitado, evidências, ação, impactos previstos e forma de acompanhar resultados","explanation":"Esses elementos permitem compreender a justificativa, antecipar efeitos e verificar se a ação alcançou o objetivo."}]},{"code":"EM13CNT101","area":"CIENCIAS_DA_NATUREZA","domain":"TRANSFORMACOES_E_CONSERVACOES","officialPage":540,"title":"Analisar transformações e conservações","officialDescription":"Analisar e representar as transformações e conservações em sistemas que envolvam quantidade de matéria, de energia e de movimento para realizar previsões em situações cotidianas e processos produtivos que priorizem o uso racional dos recursos naturais.","lesson":{"title":"Representar transformações e conservações","summary":"Definir o sistema e acompanhar matéria, energia e movimento ajuda a explicar transformações e a prever efeitos em situações cotidianas e produtivas.","content":"## Sistemas, transformações e balanços\n\nPara analisar uma transformação, primeiro delimite o sistema e identifique o que pode atravessar sua fronteira. Em um sistema aberto, matéria ou energia pode entrar e sair; por isso, uma quantidade medida dentro dele pode variar sem que a matéria ou a energia tenha sido destruída.\n\nRepresentações como diagramas, tabelas e equações organizam entradas, saídas e mudanças. A energia pode ser transferida ou transformada entre formas; a matéria pode mudar de estado ou participar de reações. No estudo do movimento, descreva posição, intervalo de tempo e interações, sem confundir velocidade com força.\n\nModelos permitem prever resultados quando suas condições são explicitadas. Em processos produtivos, compare alternativas e perdas relevantes para apoiar o uso racional dos recursos naturais. Uma previsão deve indicar dados, limites do sistema e incertezas, em vez de tratar uma representação simplificada como descrição completa.","workedExample":"Em uma chaleira elétrica, energia elétrica entra no sistema e parte é transferida para a água como energia térmica; outra parte aquece a chaleira e o ambiente. Delimitar o sistema explica por que nem toda energia fornecida aparece como aumento da temperatura da água.","tips":["Declare a fronteira do sistema antes do balanço.","Diferencie transformação de energia e transferência através da fronteira.","Use dados e condições para justificar previsões e escolhas de recursos."],"estimatedMinutes":10},"questions":[{"id":"cnt-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"SISTEMA_ABERTO","statement":"Em um tanque aberto, a massa de água medida diminui durante a evaporação. Qual explicação respeita a conservação da matéria?","options":["Parte da água passou para o ambiente como vapor e a fronteira do sistema precisa ser considerada","A matéria foi destruída porque deixou de ser líquida","A balança prova que não houve transformação","A massa só pode mudar se o recipiente mudar de cor"],"answer":"Parte da água passou para o ambiente como vapor e a fronteira do sistema precisa ser considerada","explanation":"O tanque é um sistema aberto; vapor pode sair da fronteira, então a massa dentro dele diminui embora a matéria permaneça no ambiente."},{"id":"cnt-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"TRANSFORMACAO_DE_ENERGIA","statement":"Uma lâmpada recebe energia elétrica e aquece o ambiente além de emitir luz. Qual descrição é mais adequada?","options":["A energia elétrica é transformada e transferida em diferentes formas, incluindo luz e aquecimento","Toda energia recebida se transforma apenas em luz","O aquecimento mostra que a energia desapareceu","A lâmpada cria energia sem receber nada"],"answer":"A energia elétrica é transformada e transferida em diferentes formas, incluindo luz e aquecimento","explanation":"A energia recebida não desaparece; parte é transferida como luz e parte como energia térmica para componentes e ambiente."},{"id":"cnt-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"APPLY","contextFamily":"MOVIMENTO_E_INTERACOES","statement":"Um carrinho se move em linha reta e aumenta sua velocidade em um intervalo. Que informação é necessária para analisar a mudança do movimento?","options":["O intervalo de tempo e as interações que atuam no carrinho","Somente a cor do carrinho","Apenas o valor final da velocidade, sem contexto","O formato da pista sem observar forças"],"answer":"O intervalo de tempo e as interações que atuam no carrinho","explanation":"A análise do movimento relaciona como a velocidade mudou no tempo e quais interações podem produzir essa mudança."},{"id":"cnt-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"USO_DE_RECURSOS","statement":"Uma fábrica compara dois processos que produzem a mesma quantidade de material. Qual comparação apoia melhor o uso racional de recursos?","options":["Medir entradas de matéria e energia, saídas e resíduos em condições equivalentes","Escolher o processo com a máquina mais nova sem medir resultados","Comparar só o preço da energia em meses diferentes","Ignorar resíduos porque o produto final é igual"],"answer":"Medir entradas de matéria e energia, saídas e resíduos em condições equivalentes","explanation":"Um balanço comparável permite avaliar consumo e resíduos relevantes, em vez de inferir eficiência pela aparência ou por um único indicador."},{"id":"cnt-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"PREDICT","contextFamily":"FRONTEIRA_DO_SISTEMA","statement":"Uma equipe mede menor massa de combustível no tanque após o funcionamento de um motor. O que pode ser concluído com segurança?","options":["É preciso contabilizar combustível consumido, produtos e transferências através da fronteira para interpretar o balanço","O combustível desapareceu sem transformação","A massa total do universo diminuiu","A medição não tem utilidade porque o motor funciona"],"answer":"É preciso contabilizar combustível consumido, produtos e transferências através da fronteira para interpretar o balanço","explanation":"O combustível participa de transformações e produtos podem sair do sistema; o balanço depende de quais componentes estão dentro da fronteira analisada."},{"id":"cnt-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"SYNTHESIZE","contextFamily":"PREVISAO_PRODUTIVA","statement":"Antes de prever o efeito de uma mudança em um processo produtivo, qual conjunto de decisões é mais importante?","options":["Definir sistema, grandezas, condições e dados que serão usados na comparação","Escolher uma previsão sem declarar o intervalo observado","Considerar apenas o produto final e ocultar entradas e resíduos","Tratar qualquer variação medida como violação da conservação"],"answer":"Definir sistema, grandezas, condições e dados que serão usados na comparação","explanation":"Uma previsão é interpretável e verificável quando explicita a fronteira, as grandezas e as condições do modelo."}]},{"code":"EM13CHS103","area":"CIENCIAS_HUMANAS","domain":"EVIDENCIAS_E_ARGUMENTOS","officialPage":560,"title":"Construir hipóteses com evidências","officialDescription":"Elaborar hipóteses, selecionar evidências e compor argumentos relativos a processos políticos, econômicos, sociais, ambientais, culturais e epistemológicos, com base na sistematização de dados e informações de natureza qualitativa e quantitativa (expressões artísticas, textos filosóficos e sociológicos, documentos históricos, gráficos, mapas, tabelas etc.).","lesson":{"title":"Relacionar hipóteses, fontes e evidências","summary":"Uma investigação em Ciências Humanas articula hipótese, fontes e argumentos e limita suas conclusões ao que os dados sustentam.","content":"## Investigar sem concluir além das fontes\n\nUma hipótese é uma explicação provisória para uma pergunta investigável. Para examiná-la, selecione evidências pertinentes e identifique como foram produzidas. Documentos históricos, entrevistas, textos, mapas, tabelas e expressões artísticas oferecem perspectivas e tipos de informação diferentes.\n\nSistematizar dados significa organizar critérios, períodos, categorias e fontes para que a comparação seja compreensível. Dados quantitativos podem mostrar distribuição ou variação; fontes qualitativas ajudam a interpretar sentidos, experiências e contextos. Nenhum tipo de dado responde sozinho a qualquer pergunta.\n\nAo argumentar, explique o vínculo entre evidência e hipótese, considere explicações alternativas e indique limites. Uma associação temporal ou estatística não demonstra automaticamente causalidade. A autoria, a escala, a data, a seleção da amostra e o contexto influenciam o alcance de uma conclusão. Uma hipótese pode ser revista quando novas evidências aparecem.","workedExample":"Se o número de passageiros de ônibus caiu no mesmo período em que a tarifa subiu, a tabela registra uma associação temporal. Para sustentar que a tarifa causou a queda, seria necessário examinar outros fatores, como oferta de linhas, renda, obras e mudanças de horário.","tips":["Formule uma hipótese que possa ser confrontada com fontes.","Verifique autoria, período, escala e método dos dados.","Distinga associação, explicação plausível e causalidade demonstrada."],"estimatedMinutes":10},"questions":[{"id":"chs-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"HIPOTESE_E_CAUSALIDADE","statement":"Uma tabela mostra que o uso de ônibus caiu no mesmo período em que a tarifa aumentou. Qual afirmação é sustentada diretamente por esses dados?","options":["As duas mudanças ocorreram no período observado, mas a tabela sozinha não prova que uma causou a outra","O aumento da tarifa é certamente a única causa da queda","A tabela prova que os passageiros deixaram de viajar","Não existe nenhuma relação temporal entre os dados"],"answer":"As duas mudanças ocorreram no período observado, mas a tabela sozinha não prova que uma causou a outra","explanation":"A coincidência temporal permite descrever uma associação, mas identificar causalidade exige examinar outros fatores e evidências."},{"id":"chs-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"SELECT","contextFamily":"DISTRIBUICAO_TERRITORIAL","statement":"Uma pesquisa compara o acesso a bibliotecas entre bairros. Qual evidência é mais pertinente à pergunta?","options":["Dados de localização e distância das bibliotecas com o mesmo critério para cada bairro","A opinião sobre qual bairro é mais bonito","Uma fotografia sem data nem localização","O total de livros de um país sem recorte territorial"],"answer":"Dados de localização e distância das bibliotecas com o mesmo critério para cada bairro","explanation":"Esses dados se relacionam diretamente à distribuição espacial e permitem comparar bairros com uma medida comum."},{"id":"chs-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"AUTORIA_E_CONTEXTO","statement":"Dois documentos descrevem uma greve de modos diferentes. Que procedimento ajuda a avaliar a divergência?","options":["Comparar autoria, contexto de produção, evidências usadas e finalidade de cada documento","Escolher o documento mais curto sem ler os argumentos","Considerar automaticamente neutra a fonte mais recente","Somar frases dos dois textos sem verificar quando foram produzidos"],"answer":"Comparar autoria, contexto de produção, evidências usadas e finalidade de cada documento","explanation":"Autoria e contexto ajudam a interpretar perspectivas e limites sem descartar uma fonte apenas por divergir da outra."},{"id":"chs-transfer-01","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"CORRELACAO_E_CAUSALIDADE","statement":"Uma pesquisa encontra mais bibliotecas e maior participação em consultas públicas nos mesmos bairros. O que os dados permitem afirmar?","options":["Há uma associação nos bairros observados; outros fatores e fontes precisam ser examinados antes de atribuir causalidade","As bibliotecas certamente causaram toda a diferença de participação","A associação prova que todos os moradores usam os serviços da mesma forma","Não é possível descrever qualquer padrão sem conhecer a opinião de cada morador"],"answer":"Há uma associação nos bairros observados; outros fatores e fontes precisam ser examinados antes de atribuir causalidade","explanation":"A comparação mostra um padrão conjunto, mas explicá-lo exige verificar outros fatores, método e contexto."},{"id":"chs-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ARGUMENTO_COM_DADOS","statement":"Uma entrevista relata uma experiência individual e uma tabela apresenta respostas de uma amostra. Como combiná-las?","options":["Usar a entrevista para explorar sentidos e a tabela para padrões da amostra, explicitando os limites de cada fonte","Tratar a entrevista como representação automática de toda a população","Descartar a tabela porque números nunca informam processos sociais","Somar as duas fontes como se medissem exatamente a mesma coisa"],"answer":"Usar a entrevista para explorar sentidos e a tabela para padrões da amostra, explicitando os limites de cada fonte","explanation":"Fontes qualitativas e quantitativas podem se complementar, desde que o argumento reconheça o que cada método permite afirmar."},{"id":"chs-review-01","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"ARGUE","contextFamily":"CONCLUSAO_PROVISORIA","statement":"Qual conclusão relaciona melhor uma evidência a uma hipótese sobre mudanças no emprego local?","options":["Os registros indicam uma mudança no período estudado; entrevistas e dados de outros setores podem testar explicações concorrentes","Um único número confirma definitivamente qualquer causa possível","A opinião do pesquisador substitui a análise das fontes","Se existe uma exceção, nenhuma conclusão provisória pode ser formulada"],"answer":"Os registros indicam uma mudança no período estudado; entrevistas e dados de outros setores podem testar explicações concorrentes","explanation":"A conclusão apresenta o alcance da evidência, mantém a hipótese examinável e indica fontes que podem fortalecer ou revisar a explicação."}]}]}'::jsonb;
  skill_data jsonb;
  lesson_data jsonb;
  question_data jsonb;
  catalog_id uuid;
  skill_id uuid;
  lesson_id uuid;
  question_id uuid;
  question_set_id uuid;
  existing_position integer;
  next_position integer;
  content_id text;
  validation jsonb;
  demo_keys text[] := array['demo_preview','demo_preview_only','demonstration_only','is_test_fixture','fixture_only','test_fixture','qa_only'];
begin
  select catalog.id into catalog_id
    from public.learning_curriculum_catalogs catalog
   where catalog.code = 'BNCC_2018' and catalog.active
   order by catalog.version desc
   limit 1;
  if catalog_id is null then raise exception 'GUIDED_STUDY_V13_BNCC_CATALOG_MISSING'; end if;

  for skill_data in select value from jsonb_array_elements(content->'skills') loop
    select skill.id into skill_id
      from public.learning_curriculum_skills skill
     where skill.catalog_id = catalog_id and skill.code = skill_data->>'code';
    if skill_id is null then raise exception 'GUIDED_STUDY_V13_SKILL_NOT_FOUND code=%', skill_data->>'code'; end if;
    if (select skill.metadata->>'official_code' from public.learning_curriculum_skills skill where skill.id = skill_id)
       is distinct from skill_data->>'code' then
      raise exception 'GUIDED_STUDY_V13_OFFICIAL_CODE_MISMATCH code=%', skill_data->>'code';
    end if;

    insert into public.learning_curriculum_grade_targets(
      catalog_id, stage, grade_level, subject_area, canonical_skill_id, priority, sort_order, active
    ) values (catalog_id, 'ENSINO_MEDIO', (content->>'recommendedGrade')::smallint,
      skill_data->>'area', skill_id, 10, (skill_data->>'officialPage')::integer, true)
    on conflict (catalog_id, stage, grade_level, subject_area, canonical_skill_id)
    do update set active = true, priority = excluded.priority, sort_order = excluded.sort_order, updated_at = now();

    lesson_data := skill_data->'lesson';
    insert into public.learning_skill_lessons(
      canonical_skill_id, version, title, summary, content_markdown, worked_example, tips, estimated_minutes, active, metadata
    ) values (
      skill_id, (content->>'contentVersion')::integer, lesson_data->>'title', lesson_data->>'summary',
      lesson_data->>'content', lesson_data->>'workedExample',
      array(select jsonb_array_elements_text(lesson_data->'tips')),
      (lesson_data->>'estimatedMinutes')::integer, true,
      jsonb_build_object('content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
        'official_bncc_code', skill_data->>'code', 'official_source_url', content->>'officialSourceUrl',
        'official_source_page', (skill_data->>'officialPage')::integer, 'content_origin', 'V13_REAUTHORED_FROM_V4_V8',
        'recommended_grade', (content->>'recommendedGrade')::integer,
        'recommended_grade_source', content->>'recommendedGradeSource',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING')
    ) on conflict (canonical_skill_id, version) do update set
      title = excluded.title, summary = excluded.summary, content_markdown = excluded.content_markdown,
      worked_example = excluded.worked_example, tips = excluded.tips, estimated_minutes = excluded.estimated_minutes,
      active = true, metadata = excluded.metadata, updated_at = now()
    returning id into lesson_id;

    for question_data in select value from jsonb_array_elements(skill_data->'questions') loop
      content_id := skill_data->>'code' || ':v13:' || question_data->>'id';
      select bank.id into question_id
        from public.learning_question_bank bank
       where bank.source_type = 'TECESCOLA_BNCC_GUIDED_STUDY_V13'
         and bank.metadata->>'content_id' = content_id
       limit 1;

      if question_id is null then
        insert into public.learning_question_bank(
          package_type, source_type, source_name, subject_area, domain, topic, statement, options,
          correct_answer, explanation, difficulty, cognitive_process, context_family, knowledge_mapping_status,
          knowledge_mapping_version, estimated_minutes, provenance, source_reference, metadata, active
        ) values (
          'TECESCOLA', 'TECESCOLA_BNCC_GUIDED_STUDY_V13', 'TecEscola BNCC Guided Study V13',
          skill_data->>'area', skill_data->>'domain', lower(skill_data->>'code'), question_data->>'statement',
          question_data->'options', to_jsonb(question_data->>'answer'), question_data->>'explanation',
          question_data->>'difficulty', question_data->>'cognitiveProcess', question_data->>'contextFamily',
          'READY', 'V13', 2, 'TECESCOLA_BNCC_AUTHORED_V13', content->>'officialSourceUrl',
          jsonb_build_object('content_id', content_id, 'purpose', question_data->>'purpose',
            'official_bncc_code', skill_data->>'code', 'official_source_url', content->>'officialSourceUrl',
            'official_source_page', (skill_data->>'officialPage')::integer,
            'content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
          'source_question_id', (select lineage->>'sourceQuestionId' from jsonb_array_elements(content->'conversionAudit'->'questions') lineage where lineage->>'skillCode' = skill_data->>'code' and lineage->>'contentQuestionId' = question_data->>'id'),
          'conversion_action', (select lineage->>'action' from jsonb_array_elements(content->'conversionAudit'->'questions') lineage where lineage->>'skillCode' = skill_data->>'code' and lineage->>'contentQuestionId' = question_data->>'id'),
          'content_origin', case when (select lineage->>'sourceQuestionId' from jsonb_array_elements(content->'conversionAudit'->'questions') lineage where lineage->>'skillCode' = skill_data->>'code' and lineage->>'contentQuestionId' = question_data->>'id') is null then 'V13_NEW_SUPPLEMENT' else 'V13_REAUTHORED_V8' end,
            'recommended_grade', (content->>'recommendedGrade')::integer,
            'recommended_grade_source', content->>'recommendedGradeSource',
            'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING'), true
        ) returning id into question_id;
      else
        update public.learning_question_bank bank set
          subject_area = skill_data->>'area', domain = skill_data->>'domain', topic = lower(skill_data->>'code'),
          statement = question_data->>'statement', options = question_data->'options',
          correct_answer = to_jsonb(question_data->>'answer'), explanation = question_data->>'explanation',
          difficulty = question_data->>'difficulty', cognitive_process = question_data->>'cognitiveProcess',
          context_family = question_data->>'contextFamily', knowledge_mapping_status = 'READY',
          knowledge_mapping_version = 'V13', estimated_minutes = 2, provenance = 'TECESCOLA_BNCC_AUTHORED_V13',
          source_reference = content->>'officialSourceUrl',
          metadata = jsonb_build_object('content_id', content_id, 'purpose', question_data->>'purpose',
            'official_bncc_code', skill_data->>'code', 'official_source_url', content->>'officialSourceUrl',
            'official_source_page', (skill_data->>'officialPage')::integer,
            'content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
            'source_question_id', (select lineage->>'sourceQuestionId' from jsonb_array_elements(content->'conversionAudit'->'questions') lineage where lineage->>'skillCode' = skill_data->>'code' and lineage->>'contentQuestionId' = question_data->>'id'),
            'conversion_action', (select lineage->>'action' from jsonb_array_elements(content->'conversionAudit'->'questions') lineage where lineage->>'skillCode' = skill_data->>'code' and lineage->>'contentQuestionId' = question_data->>'id'),
            'content_origin', case when (select lineage->>'sourceQuestionId' from jsonb_array_elements(content->'conversionAudit'->'questions') lineage where lineage->>'skillCode' = skill_data->>'code' and lineage->>'contentQuestionId' = question_data->>'id') is null then 'V13_NEW_SUPPLEMENT' else 'V13_REAUTHORED_V8' end,
            'recommended_grade', (content->>'recommendedGrade')::integer,
            'recommended_grade_source', content->>'recommendedGradeSource',
            'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING'),
          active = true, updated_at = now()
        where bank.id = question_id;
      end if;

      insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
      values (question_id, skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;

      insert into public.learning_question_sets(
        scope, canonical_skill_id, purpose, version, difficulty, active, metadata
      ) values (
        'GLOBAL', skill_id, question_data->>'purpose', (content->>'contentVersion')::integer,
        question_data->>'difficulty', true,
        jsonb_build_object('content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
          'official_bncc_code', skill_data->>'code', 'selection_policy', 'UNSEEN_FIRST_LIMIT_TWO',
          'recommended_grade', (content->>'recommendedGrade')::integer,
          'recommended_grade_source', content->>'recommendedGradeSource',
          'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING')
      ) on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL'
      do update set difficulty = excluded.difficulty, active = true, metadata = excluded.metadata, updated_at = now()
      returning id into question_set_id;

      select item.position into existing_position
        from public.learning_question_set_items item
       where item.question_set_id = question_set_id and item.question_bank_id = question_id;
      if not found then
        select coalesce(max(item.position), -1) + 1 into next_position
          from public.learning_question_set_items item where item.question_set_id = question_set_id;
        insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
        values (question_set_id, question_id, next_position);
      end if;
    end loop;

    update public.learning_curriculum_skills skill set
      metadata = (coalesce(skill.metadata, '{}'::jsonb) - demo_keys) || jsonb_build_object(
        'official_code', skill_data->>'code', 'official_source_id', 'BNCC_EM_2018',
        'official_source_url', content->>'officialSourceUrl', 'official_source_page', (skill_data->>'officialPage')::integer,
        'official_grade_range', '1-3', 'mapping_status', 'MAPPED',
        'mapping_source', 'TECESCOLA_BNCC_V13_RECONCILIATION',
        'content_pack', content->>'packVersion', 'content_version', (content->>'contentVersion')::integer,
        'content_origin', 'V13_REAUTHORED_FROM_V4_V8',
        'source_content_versions', jsonb_build_array('TECESCOLA_BNCC_HIGH_SCHOOL_FIRST_YEAR_V4','TECESCOLA_BNCC_DEEP_LEARNING_V8'),
        'recommended_grade', (content->>'recommendedGrade')::integer,
        'recommended_grade_source', content->>'recommendedGradeSource',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING'
      ),
      subject_area = skill_data->>'area', domain = skill_data->>'domain', title = skill_data->>'title',
      description = skill_data->>'officialDescription', stage = 'ENSINO_MEDIO', grade_level = null,
      active = true, node_kind = 'LEAF', content_readiness = 'CONTENT_READY', mastery_targetable = false,
      bncc_alignment_status = 'MAPPED', publication_status = 'STAGING',
      pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING', updated_at = now()
     where skill.id = skill_id;

    select private.validate_mapped_bncc_skill_v12(skill_id, skill_data->>'code', skill.metadata)
      into validation from public.learning_curriculum_skills skill where skill.id = skill_id;
    if validation->>'status' <> 'READY' then
      raise exception 'GUIDED_STUDY_V13_SKILL_VALIDATION_FAILED code=% result=%', skill_data->>'code', validation;
    end if;
    if not exists (
      select 1 from public.learning_curriculum_skills skill
       where skill.id = skill_id and skill.publication_status = 'PUBLISHED'
         and skill.technical_validation_status = 'PUBLISHED'
         and skill.content_readiness = 'ADAPTIVE_READY' and skill.mastery_targetable
         and skill.bncc_alignment_status = 'MAPPED'
         and skill.pedagogical_review_status = 'PEDAGOGICAL_REVIEW_PENDING'
    ) then
      raise exception 'GUIDED_STUDY_V13_AUTOMATIC_PUBLICATION_FAILED code=%', skill_data->>'code';
    end if;
  end loop;

  if not exists (
    select 1 from public.learning_adaptive_content_packs pack
     where pack.pack_version = content->>'packVersion' and pack.active
       and pack.publication_status = 'PUBLISHED' and pack.technical_validation_status = 'PUBLISHED'
  ) then raise exception 'GUIDED_STUDY_V13_PACK_VALIDATION_FAILED'; end if;
end;
$guided_study_v13_content_seed$;

notify pgrst, 'reload schema';
commit;
